-- Resources content for copy dedicated to one schedule line (CLAUDE.md,
-- "Resources stay in step with the code"; docs/underwriting-traffic-
-- redesign.md §16). Content only; the schema change is
-- 20260930150000_underwriting_line_scoped_copy.sql.

select private.rc_release_guide(
  p_slug => 'underwriting-copy-and-placement',
  p_tool_key => 'underwriting',
  p_title => 'Copy, rotation, and placing a credit',
  p_summary => 'Link a contract''s messages, dedicate one to a line where the order says so, then place a credit manually or let auto-fill do it.',
  p_screen_keys => array['underwriting.contract', 'underwriting.copy'],
  p_sort_order => 30,
  p_version_note => 'A message can be dedicated to one line',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A credit needs approved copy behind it before it can run anywhere."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Copy"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the contract's Copy tab, select "},{"type":"text","text":"+ New message","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Link existing…","marks":[{"type":"bold"}]},{"type":"text","text":" to attach a script. A draft message can be approved right from its card — only approved copy rotates or gets placed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Copy shared across more than one contract shows which others use it, right on its edit card."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Rotation"}]},{"type":"paragraph","content":[{"type":"text","text":"Rotation is automatic: each contract cycles through its own linked messages in broadcast order, with nothing for staff to pick. An aired, frozen, or manager-overridden placement is a fixed point that rotation won't move."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A message for one line"}]},{"type":"paragraph","content":[{"type":"text","text":"Some orders give a message to one line rather than to the whole contract — for example, “For Carpool: #1” and “For Total Program: #2”. When linking the message, choose the line under "},{"type":"text","text":"Use on","marks":[{"type":"bold"}]},{"type":"text","text":", or use "},{"type":"text","text":"Use on one line only…","marks":[{"type":"bold"}]},{"type":"text","text":" from a linked message's menu."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A message dedicated to a line airs only on that line."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"That line then airs only its own messages. If it has more than one, they rotate among themselves."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Every other line keeps rotating the contract's other messages, as before."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If a revision replaces the line, the message's card shows "},{"type":"text","text":"Line replaced — set it again","marks":[{"type":"bold"}]},{"type":"text","text":"; choose the new line."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Placing a credit"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Manually, from a schedule line's "},{"type":"text","text":"Place a credit","marks":[{"type":"bold"}]},{"type":"text","text":" link: pick an open break (grouped by period), confirm or change the suggested message (already the next one in rotation), and select "},{"type":"text","text":"Place credit","marks":[{"type":"bold"}]},{"type":"text","text":". Only messages that may air on that line are offered."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Or let auto-fill do it: "},{"type":"text","text":"Auto-fill this line","marks":[{"type":"bold"}]},{"type":"text","text":" from a line's own menu, "},{"type":"text","text":"Auto-fill this contract","marks":[{"type":"bold"}]},{"type":"text","text":" for every line on one contract, or "},{"type":"text","text":"Auto-fill everything","marks":[{"type":"bold"}]},{"type":"text","text":" for every active contract — the same placement path either way, just run in a loop."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A same-underwriter or same-industry adjacency warning is advisory on the manual placement form — it's shown, never blocked."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Auto-fill generates the rundowns it needs as it goes, so a fresh contract can be filled for its whole campaign in one click even before a rundown for those dates exists yet."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-09-30-underwriting-line-scoped-copy',
  p_tool_key => 'underwriting',
  p_released_on => '2026-09-30',
  p_title => 'A message can be dedicated to one line',
  p_guide_slugs => array['underwriting-copy-and-placement'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A message can now be dedicated to one line of a contract, the way some insertion orders give their Carpool spots a script of their own. That line airs only its own messages, and the contract's other lines keep rotating the rest. Choose the line when linking a message on the contract's Copy tab, or from a linked message's menu."}]}]}$body$
);
